def preencher_dias_e_regularizacao(apps, schema_editor):
    ParcelaContrato = apps.get_model('contracts', 'ParcelaContrato')
    PagamentoContrato = apps.get_model('contracts', 'PagamentoContrato')
    for parcela in ParcelaContrato.objects.filter(
        tipo__in=['semanal', 'mensal'], dias__isnull=True,
    ).select_related('contrato'):
        diaria = parcela.contrato.diaria
        if not diaria:
            continue
        dias = parcela.valor / diaria
        if dias == dias.to_integral_value() and dias > 0:
            parcela.dias = int(dias)
            parcela.save(update_fields=['dias'])
    PagamentoContrato.objects.filter(
        tipo='locacao', parcela__isnull=True, contrato__origem_retroativa=True,
        observacoes__startswith='Regularização de saldo pré-sistema',
    ).update(tipo='regularizacao')


def reverter_regularizacao(apps, schema_editor):
    PagamentoContrato = apps.get_model('contracts', 'PagamentoContrato')
    PagamentoContrato.objects.filter(tipo='regularizacao').update(tipo='locacao')


